        answer: ['日本[にほん]は現金主義[げんきんしゅぎ]が根強[ねづよ]いと言[い]われますが、ここ数年[すうねん]でQRコード決済[けっさい]が一気[いっき]に普及[ふきゅう]し、利用者[りようしゃ]は増[ふ]える一方[いっぽう]です。私[わたし]も以前[いぜん]は現金派[げんきんは]でしたが、ポイント還元[かんげん]をきっかけに、キャッシュレスに踏[ふ]み切[き]りました。ただ、普及[ふきゅう]に伴[ともな]い不正利用[ふせいりよう]の被害[ひがい]も増[ふ]えており、便利[べんり]だからといって安全[あんぜん]とは限[かぎ]りません。また、店側[みせがわ]の手数料[てすうりょう]の負担[ふたん]や、スマホに慣[な]れない高齢者[こうれいしゃ]が取[と]り残[のこ]されることも懸念[けねん]されています。現金[げんきん]もキャッシュレスも、選[えら]べる社会[しゃかい]であってほしいと思[おも]います。',
          'They say cash is deeply rooted in Japan, but in the last few years QR-code payment has spread rapidly and users just keep increasing. I used to prefer cash too, but points rewards got me to take the plunge and go cashless. However, along with its spread, losses from fraudulent use are also increasing, and just because something is convenient doesn\'t mean it\'s safe. There are also concerns about the fees shops have to bear, and about elderly people who aren\'t used to smartphones being left behind. I hope we stay a society where people can choose either cash or cashless.'],
